Method.Source:
/// <summary>
/// Instead of using initInventDimParmInventTrans which is getting InventDimSetupGrid.ShowGridInventTrans (site and WMSLocationId)
/// Force the display dimensions to site and warehouse for ISP inventory transactions
/// </summary>
/// <param name = "_inventDimParm"></param>
static void METInitInventDimParmInventTrans(InventDimParm  _inventDimParm)
{
    _inventDimParm.InventSiteIdFlag = NoYes::Yes;
    _inventDimParm.InventLocationIdFlag = NoYes::Yes;

}
